function stripPrefix(s: string): string {
  const prefixes = ['MUNICIPIUL ', 'ORAȘUL ', 'COMUNA ', 'JUDEȚUL ', 'JUDETUL ']
  const upper = s.trim().toUpperCase()
  for (const p of prefixes) {
    if (upper.startsWith(p)) {
      return s.trim().slice(p.length).trim()
    }
  }
  return s.trim()
}

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z]/g, '')
}

export function resolveSiruta(
  cui: string | null,
  locality: string,
  county: string
): string | null {
  // Try CUI first
  if (cui) {
    const cuiStr = cui.trim()
    if (UAT_CUI_TO_NATCODE[cuiStr]) {
      return UAT_CUI_TO_NATCODE[cuiStr]
    }
  }

  // Fallback to locality + county (strip prefixes)
  if (county !== 'Național') {
    const stripped = stripPrefix(locality)
    const key = `${normalize(stripped)}|${normalize(county)}`
    if (UAT_LOCALITY_TO_NATCODE[key]) {
      return UAT_LOCALITY_TO_NATCODE[key]
    }
  }

  return null
}
